534:         /* 关键修复（问题3）：仅当实际硬件引脚检测到低电平（0=BUSY播放中）时，才置位 s_seg_busy_seen！
535:          * 切勿直接调用 BSP_Audio_IsBusy()，因其内部在 s_seg_active!=0 时恒为 1，会导致误判立即结束 */
536:         if (HAL_GPIO_ReadPin(AUDIO_BUSY_GPIO_Port, AUDIO_BUSY_Pin) == GPIO_PIN_RESET)
537:         {
538:             s_seg_busy_seen = 1U;
539:         }
540: 
541:         /* 有 PLAY 还在队列里没发出去时不作判定，避免重复入队 */
542:         if (!audio_req_has(AOP_PLAY) && !audio_req_has(AOP_STOP))
543:         {
544:             busy = (HAL_GPIO_ReadPin(AUDIO_BUSY_GPIO_Port, AUDIO_BUSY_Pin) == GPIO_PIN_RESET) ? 1U : 0U;
545:             if (((now - s_seg_tick) > AUDIO_SEG_MIN_MS) &&
546:                 ((s_seg_busy_seen && !busy) ||
547:                  ((now - s_seg_tick) > AUDIO_SEG_TIMEOUT_MS)))
548:             {
549:                 s_seg_active = 0U;
550:                 s_q_idx++;
551:                 if (s_q_idx < s_q_count)
552:                 {
553:                     audio_req_push(AOP_PLAY, s_queue[s_q_idx]);
554:                 }
555:                 else
556:                 {
557:                     s_q_count = 0U;
558:                     s_q_idx   = 0U;
559:                     /* 关键修复（问题4）：播报队列播放完毕后，自动向 N9300 下发停止指令使 DAC 进入低功耗静音模式，
560:                      * 彻底解决 8002A 功放悬空偏置引发的喇叭持续“突突突”电机船/振荡杂音 */
561:                     audio_req_push(AOP_STOP, 0U);
562:                 }
563:             }
564:         }
565:     }
566: 
567:     /* 6. 开机循环播放测试 */
568:     if ((s_loop_on != 0U) && (s_req_cnt == 0U) && (s_seg_active == 0U))
569:     {
570:         if ((int32_t)(now - s_loop_next_tick) >= 0)
571:         {
572:             audio_req_push(AOP_PLAY, s_loop_cur);
573:             s_loop_next_tick = now + s_loop_interval;
574:             s_loop_cur = (s_loop_cur >= s_loop_last) ? s_loop_first : (uint16_t)(s_loop_cur + 1U);
575:         }
576:     }
577: }
