337: /* ======================= 接收解析 ======================= */
338: static void audio_rx_parse(uint8_t b)
339: {
340:     uint8_t need;
341:     uint8_t len;
342:     uint8_t i;
343:     uint8_t sum = 0U;
344: 
345:     if (s_rx_len == 0U)
346:     {
347:         s_rx_frame[s_rx_len++] = b;
348:         return;
349:     }
350: 
351:     if (s_rx_len < AUDIO_FRAME_MAX_LEN)
352:     {
353:         s_rx_frame[s_rx_len++] = b;
354:     }
355:     else
356:     {
357:         s_rx_len = 0U;
358:         return;
359:     }
360: 
361:     if (s_rx_len < 3U) return;
362: 
363:     len = s_rx_frame[2];
364:     if (len > 20U)
365:     {
366:         s_rx_len = 0U;
367:         return;
368:     }
369:     need = (uint8_t)(3U + len + 1U);
370:     if (s_rx_len < need) return;
371: 
372:     /* 命令码 + 反码 校验 */
373:     if ((uint8_t)(s_rx_frame[0] ^ 0xFFU) != s_rx_frame[1])
374:     {
375:         s_rx_len = 0U;
376:         return;
377:     }
378:     /* 校验和 */
379:     for (i = 0U; i < need - 1U; i++) sum = (uint8_t)(sum + s_rx_frame[i]);
380:     if (sum != s_rx_frame[need - 1U])
381:     {
382:         s_rx_len = 0U;
383:         return;
384:     }
385: 
386:     s_last_ack_cmd = s_rx_frame[0];
387:     s_online = 1U;
388: 
389:     if (s_rx_frame[0] == 0xAAU && len >= 2U && s_rx_frame[3] == 0xFFU)
390:     {
391:         s_last_error = s_rx_frame[4];
392:     }
393:     else if (s_rx_frame[0] == 0x04U && len >= 1U)
394:     {
395:         s_last_error = 0U;
396:     }
397: 
398:     s_rx_len = 0U;
399: }
